INSERT INTO "planning_directions" ("direction_id","direction_order","title","state","detail_doc_path","content_json") VALUES ('general-workstream',0,'General workstream','active','','{"id":"general-workstream","title":"General workstream","summary":"No detailed direction taxonomy is defined yet. After each main result, evaluate the latest user request and accepted answer against this generic direction, capture the next queue-driven task in DB task authority, and work from the derived queue.","success_criteria":["Actionable goals are represented in DB task authority as queue-driven execution slices.","When the latest request and main result leave a clear follow-up, gap, or verification need, that queue-head task is derived into task authority instead of leaving the queue idle.","Work advances by updating task authority instead of inventing unmanaged side tasks."],"scope_hints":["Use this generic direction until the operator replaces it with a richer direction catalog.","Represent concrete next actions and proposals in accepted task authority.","If the user asked for a multi-step artifact, evaluate the latest main result and queue the next concrete slice only when the follow-up is clear."],"detail_doc_path":"","state":"active"}');
